#include "app.h"
#include <gccore.h>
#include <ogc/gx.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <malloc.h>
/* Preprocessed native GX RGBA8 tiles. No PNG decoding, no network calls or
 * large allocations on every rendered frame. Generated by cover_sync.py. */
#define COV_W 128
#define COV_H 160
#define COV_BYTES (COV_W*COV_H*4)
typedef struct { char key[120]; void *pixels; int valid; unsigned last; GXTexObj tex; } Cache;
static Cache cache[5];static unsigned clock_id=0;
static void key_for(const Game*g,char*key,size_t cap){
 if(g->id[0]){snprintf(key,cap,"%s",g->id);return;}
 size_t n=0;for(const char*p=g->name;*p&&n+1<cap;p++){
  unsigned char c=(unsigned char)*p;if(c>='a'&&c<='z')c-=32;
  if((c>='A'&&c<='Z')||(c>='0'&&c<='9'))key[n++]=c;
  else if(c==' '&&n&&key[n-1]!='-')key[n++]='-';
 }key[n]=0;
}
static Cache*lookup(const Game*g){
 char key[120];key_for(g,key,sizeof(key));if(!*key)return NULL;
 clock_id++;
 for(int j=0;j<5;j++)if(cache[j].key[0]&&!strcmp(cache[j].key,key)){
  cache[j].last=clock_id;return cache[j].valid?&cache[j]:NULL;
 }
 int slot=-1;for(int j=0;j<5;j++)if(!cache[j].key[0]){slot=j;break;}
 if(slot<0){slot=0;for(int j=1;j<5;j++)if(cache[j].last<cache[slot].last)slot=j;}
 Cache*c=&cache[slot];free(c->pixels);memset(c,0,sizeof(*c));
 snprintf(c->key,sizeof(c->key),"%s",key);c->last=clock_id;
 char p[200];FILE*f=NULL;
 for(int root=0;root<2;root++){
  snprintf(p,sizeof(p),"%s:/maizo/covers/%s.gxt",root?"sd":"usb",key);
  f=fopen(p,"rb");if(f)break;
 }
 if(!f)return NULL;
 unsigned char hdr[8];
 if(fread(hdr,1,8,f)!=8||memcmp(hdr,"MZG1",4)||hdr[4]!=0||hdr[5]!=COV_W||hdr[6]!=0||hdr[7]!=COV_H){fclose(f);return NULL;}
 c->pixels=memalign(32,COV_BYTES);if(!c->pixels){fclose(f);return NULL;}
 if(fread(c->pixels,1,COV_BYTES,f)!=COV_BYTES){free(c->pixels);c->pixels=NULL;fclose(f);return NULL;}
 fclose(f);DCFlushRange(c->pixels,COV_BYTES);
 GX_InitTexObj(&c->tex,c->pixels,COV_W,COV_H,GX_TF_RGBA8,GX_CLAMP,GX_CLAMP,GX_FALSE);
 GX_InitTexObjLOD(&c->tex,GX_LINEAR,GX_LINEAR,0.0f,0.0f,0.0f,GX_FALSE,GX_FALSE,GX_ANISO_1);
 c->valid=1;return c;
}
static void vertex(float x,float y,float s,float t){
 GX_Position2f32(x,y);GX_Color4u8(255,255,255,255);GX_TexCoord2f32(s,t);
}
int cover_draw(const Game*g,float x,float y,float w,float h){
 Cache*c=lookup(g);if(!c)return 0;
 GX_SetNumTexGens(1);GX_SetTexCoordGen(GX_TEXCOORD0,GX_TG_MTX2x4,GX_TG_TEX0,GX_IDENTITY);
 GX_SetVtxDesc(GX_VA_TEX0,GX_DIRECT);
 GX_SetVtxAttrFmt(GX_VTXFMT0,GX_VA_TEX0,GX_TEX_ST,GX_F32,0);
 GX_SetTevOp(GX_TEVSTAGE0,GX_MODULATE);
 GX_LoadTexObj(&c->tex,GX_TEXMAP0);
 GX_Begin(GX_QUADS,GX_VTXFMT0,4);
 vertex(x,y,0,0);vertex(x+w,y,1,0);vertex(x+w,y+h,1,1);vertex(x,y+h,0,1);
 GX_End();
 GX_SetVtxDesc(GX_VA_TEX0,GX_NONE);GX_SetNumTexGens(0);
 GX_SetTevOp(GX_TEVSTAGE0,GX_PASSCLR);
 return 1;
}
